#!/usr/bin/env bash
set -euo pipefail
HERE=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
export ALE_SETTINGS='{"exact_limit": 0, "bond": 160, "sweeps": 14, "step": 0.04, "energy_tol": 1e-11, "eig_tol": 2e-12, "cutoff": 1e-16, "optimize_layout": false, "general_symmetry": false, "davidson_tol": 1e-15, "krylov_tol": 1e-18, "spin_orbitals": true, "number_as_sz": false, "one_site_after": null, "sparse_memory_limit_mb": 2600, "threads": 2, "seed": 1729, "normalization_during_evolution": false, "sector": {"kind": "parity", "value": 1}, "sector_dimension": 32768, "estimated_sparse_mb": 161.96875, "method": "two-site DMRG and two-site TDVP", "tensor_layout": [9, 6, 7, 2, 3, 10, 0, 1, 8, 11, 4, 5], "symmetry_implementation": "general Abelian modes", "local_electronic_dimension": 2, "initial_bond": 32, "bond_schedule": [32, 32, 64, 64, 160], "mode_layout_override": [9, 6, 7, 2, 3, 10, 0, 1, 8, 11, 4, 5]}'
